    const atkHomeBonusP=atkHomeP?1.5:1;
    if(atkHomeP) narrative.push(`🏠 ${atkName} fights to win back ${prov.name}, the realm's own capital — home ground lends the assault ×1.5 strength.`);
    let defBonus=1.25*(isHome?1.2:1);
