    // lists are the single source of each side's force product — the ladder prints them as they are.
    const _pAtkFM=[{label:'fanaticism',m:atkFanMult},{label:'discoveries',m:atkDiscBonus},{label:'duel morale',m:atkMorale},{label:'consecrated ground',m:_consecPenalty},{label:'sanctuary wards',m:atkSanct},{label:'orders',m:atkOrd},{label:'home ground',m:atkHomeBonusP}];
    const _pDefFM=[{label:'fanaticism',m:defFanMult},{label:"defender's position",m:defBonus},{label:'duel morale',m:defMorale},{label:'discoveries',m:defDiscBonus},{label:'sanctuary wards',m:defSanct},{label:'orders',m:defOrd}];
    const _gA={}, _gD={};
    finishSide(atkRows,pvpFront,atkFlankPvp,_pAtkFM,{terrain:pvpTerrain,tac:atkTact,enemy:defRows,enemyTac:defTact,out:_gA});
    finishSide(defRows,pvpFront,defFlankPvp,_pDefFM,{terrain:pvpTerrain,tac:defTact,enemy:atkRows,enemyTac:atkTact,out:_gD});
