    const _dep=battleDeploy(atkRows,defRows,{terrain:pvpTerrain,roll:pvpFront,tacA:atkTact,tacD:defTact,flankA:atkFlankPvp,flankD:defFlankPvp,scout:battleScout(_explA,_explD)});
