    // the harness asserts lineTotal × Π(m) === baseStr for both sides.
    narrative.push(`📊 **Battle stats:**`);
    narrative.push(...ladderLines('Attacker', atkName, atkRows, pvpFront, atkFlankPvp, _pAtkFM, atkBaseStr, {grid:_gA.grid, tact:(pvpIsLand&&atkTactBonus>1)?{mult:tacMulted(atkTactBonus,atk),label:`Tactical ${atkTact} ${ladderFm(tacMulted(atkTactBonus,atk))}`}:null}));
    narrative.push(...ladderLines('Defender', defName, defRows, pvpFront, defFlankPvp, _pDefFM, defBaseStr, {grid:_gD.grid, tact:(pvpIsLand&&defTactBonus>1)?{mult:tacMulted(defTactBonus,def),label:`Tactical ${defTact} ${ladderFm(tacMulted(defTactBonus,def))}`}:null}));
