    { const _wp=won?atk.player:def.player; if(prov.race==='Orcish'&&_wp!=null&&G.players[_wp]&&G.players[_wp].race==='Orcish') prov._raidersMuster=G.turn; }
    // Tactical gain deferred to the end of the battle narrative — see the return below.
